export default {
  testDir: '/tmp/audit-exp',
  fullyParallel: true,
  reporter: [['list']],
  use: { baseURL: 'http://localhost:3000' },
};

// Experiments for the audit. Each test applies a WRONG action or a wrong state
// and then runs the original assertions. A passing experiment = the assertion is vacuous.
const P = '/Users/arsenvlasov/Documents/WorkFolder/harness-demo-runs/desk-r/tests';
import { expect, test } from '/Users/arsenvlasov/Documents/WorkFolder/harness-demo-runs/desk-r/tests/fixtures';
import { BasketPage, ProductListPage, TopBar } from '/Users/arsenvlasov/Documents/WorkFolder/harness-demo-runs/desk-r/tests/pages/shop';
import { PRODUCTS, PURCHASE_LIMIT_MESSAGE, DELIVERY, INVALID_COUPON } from '/Users/arsenvlasov/Documents/WorkFolder/harness-demo-runs/desk-r/tests/helpers/test-data';
import { addMoneyToWallet, addSavedAddress, addSavedCard } from '/Users/arsenvlasov/Documents/WorkFolder/harness-demo-runs/desk-r/tests/helpers/api';
import { couponCode } from '/Users/arsenvlasov/Documents/WorkFolder/harness-demo-runs/desk-r/tests/helpers/coupon';
import { AddressPage, DeliveryPage, PaymentPage } from '/Users/arsenvlasov/Documents/WorkFolder/harness-demo-runs/desk-r/tests/pages/checkout';
void P;

test('E1 TC-04 step 5 without clicking Add to Basket', async ({ loggedInPage: page }) => {
  const products = new ProductListPage(page);
  const topBar = new TopBar(page);
  const basket = new BasketPage(page);
  const product = PRODUCTS.apple;
  await products.goto();
  await products.addToBasket(product.name);
  await topBar.openBasket();
  for (let q = 2; q <= 5; q++) {
    await basket.increase(product.name).click();
    await basket.expectRow(product.name, q);
  }
  await basket.increase(product.name).click();
  await products.expectMessage(PURCHASE_LIMIT_MESSAGE);
  await basket.expectRow(product.name, 5);
  await basket.expectTotal('9.95¤');
  await topBar.expectBasketCounter(5);
  // step 5, but NO click on Add to Basket
  await products.goto();
  await products.expectMessage(PURCHASE_LIMIT_MESSAGE);
  await topBar.expectBasketCounter(5);
});

test('E2 TC-07 step 9 assertions with a NON-empty basket', async ({ loggedInPage: page }) => {
  const products = new ProductListPage(page);
  const topBar = new TopBar(page);
  const basket = new BasketPage(page);
  await products.search(PRODUCTS.eggfruit.name);
  await products.addToBasket(PRODUCTS.eggfruit.name);
  await products.search(PRODUCTS.carrot.name);
  await products.addToBasket(PRODUCTS.carrot.name);
  await topBar.openBasket();
  await basket.expectNoRow(PRODUCTS.eggfruit.name);
  await basket.expectNoRow(PRODUCTS.carrot.name);
  await expect(basket.checkoutButton).toBeDisabled({ timeout: 1000 });
});

test('E2b TC-07 step 9 row checks only, NON-empty basket', async ({ loggedInPage: page }) => {
  const products = new ProductListPage(page);
  const topBar = new TopBar(page);
  const basket = new BasketPage(page);
  await products.search(PRODUCTS.eggfruit.name);
  await products.addToBasket(PRODUCTS.eggfruit.name);
  await topBar.openBasket();
  await basket.expectNoRow(PRODUCTS.eggfruit.name);
});

test('E3 TC-03 step 4 assertions after clicking PLUS instead of minus', async ({ loggedInPage: page }) => {
  const products = new ProductListPage(page);
  const topBar = new TopBar(page);
  const basket = new BasketPage(page);
  const a = PRODUCTS.raspberry, b = PRODUCTS.eggfruit;
  await products.search(a.name);
  await products.addToBasket(a.name);
  await products.search(b.name);
  await products.addToBasket(b.name);
  await topBar.openBasket();
  await basket.expectRow(a.name, 1);
  await basket.expectTotal('13.98¤');
  // wrong action: quantity goes to 2
  await basket.increase(a.name).click();
  await basket.expectRow(a.name, 1);
  await basket.expectTotal('13.98¤');
});

test('E4 TC-08 step 6 balance check with balance 5.00 (no top-up)', async ({ loggedInPage: page, customer, request }) => {
  const products = new ProductListPage(page);
  const topBar = new TopBar(page);
  const basket = new BasketPage(page);
  const addressPage = new AddressPage(page);
  const deliveryPage = new DeliveryPage(page);
  const paymentPage = new PaymentPage(page);
  const cardId = await addSavedCard(request, customer.token);
  await addSavedAddress(request, customer.token);
  await addMoneyToWallet(request, customer.token, cardId, 5);
  await products.goto();
  await products.addToBasket(PRODUCTS.eggfruit.name);
  await topBar.openBasket();
  await basket.checkoutButton.click();
  await addressPage.selectSavedAddress();
  await addressPage.continue();
  await deliveryPage.select(DELIVERY.standard.name);
  await deliveryPage.continue();
  await paymentPage.expectOpen();
  await expect(page.locator('body')).toContainText('8.99');
});

test('E5 TC-06 step 4 assertions after redeeming a VALID coupon', async ({ loggedInPage: page, customer, request }) => {
  const products = new ProductListPage(page);
  const topBar = new TopBar(page);
  const basket = new BasketPage(page);
  const addressPage = new AddressPage(page);
  const deliveryPage = new DeliveryPage(page);
  const paymentPage = new PaymentPage(page);
  await addSavedAddress(request, customer.token);
  await addSavedCard(request, customer.token);
  await products.goto();
  await products.addToBasket(PRODUCTS.eggfruit.name);
  await topBar.openBasket();
  await basket.checkoutButton.click();
  await addressPage.selectSavedAddress();
  await addressPage.continue();
  await deliveryPage.select(DELIVERY.oneDay.name);
  await deliveryPage.continue();
  await paymentPage.expectOpen();
  await paymentPage.redeemCoupon(INVALID_COUPON);
  await expect(page.getByText('Invalid coupon.')).toBeVisible();
  // step 4 with the CURRENT (valid) coupon instead of the expired one
  await paymentPage.couponField.fill(couponCode(10));
  await paymentPage.redeemButton.click();
  await expect(page.getByText('Invalid coupon.')).toBeVisible();
  await expect(page.getByText('Your discount of')).toHaveCount(0);
});

test('E6 TC-06 step 3 with INVALID_COUPON i18n text replaced', async ({ loggedInPage: page, customer, request }) => {
  await page.route('**/assets/i18n/en.json', async (route) => {
    const resp = await route.fetch();
    const json = await resp.json();
    json.INVALID_COUPON = 'MUT';
    await route.fulfill({ response: resp, json });
  });
  await page.reload();
  const products = new ProductListPage(page);
  const topBar = new TopBar(page);
  const basket = new BasketPage(page);
  const addressPage = new AddressPage(page);
  const deliveryPage = new DeliveryPage(page);
  const paymentPage = new PaymentPage(page);
  await addSavedAddress(request, customer.token);
  await addSavedCard(request, customer.token);
  await products.goto();
  await products.addToBasket(PRODUCTS.eggfruit.name);
  await topBar.openBasket();
  await basket.checkoutButton.click();
  await addressPage.selectSavedAddress();
  await addressPage.continue();
  await deliveryPage.select(DELIVERY.oneDay.name);
  await deliveryPage.continue();
  await paymentPage.expectOpen();
  await paymentPage.redeemCoupon(INVALID_COUPON);
  await page.waitForTimeout(1500);
  const panel = await page.locator('mat-expansion-panel').allInnerTexts();
  console.log('E6 PANEL TEXT:', JSON.stringify(panel));
  console.log('E6 Invalid coupon. count:', await page.getByText('Invalid coupon.').count());
  console.log('E6 MUT count:', await page.getByText('MUT', { exact: true }).count());
});

test('E7 TC-01 step 5 source of the email in the account menu', async ({ page, customer }) => {
  const seen: string[] = [];
  page.on('request', (r) => { if (r.url().includes('whoami')) seen.push(r.url()); });
  await page.route(/\/rest\/user\/whoami\?fields=email$/, async (route) => {
    const resp = await route.fetch();
    const json = await resp.json();
    if (json.user) json.user.email = 'mut@example.test';
    await route.fulfill({ response: resp, json });
  });
  const { LoginPage } = await import('/Users/arsenvlasov/Documents/WorkFolder/harness-demo-runs/desk-r/tests/pages/login');
  const login = new LoginPage(page);
  const topBar = new TopBar(page);
  await login.goto();
  await login.login(customer.email, customer.password);
  await expect(page).toHaveURL(/#\/search/);
  await topBar.openAccountMenu();
  await page.waitForTimeout(1000);
  console.log('E7 whoami requests:', JSON.stringify(seen));
  console.log('E7 MENU TEXT:', JSON.stringify(await topBar.accountMenu.innerText()));
  console.log('E7 mut visible anywhere:', await page.getByText('mut@example.test').count());
});
